set -e
cd "$(dirname "$0")"
mkdir -p site
printf '%s\n' 'hello from surl' > site/hello.txt
printf '%s\n' 'uploaded over ftp' > notes.txt
printf '%s\n' 'uploaded over http' > reply.txt
surl --directory site --allow-anonymous --allow-uploads ftp://127.0.0.1:8080/ http://127.0.0.1:8081/ &
sleep 1
curl -T notes.txt ftp://127.0.0.1:8080/notes.txt --next http://127.0.0.1:8081/notes.txt
kill $(jobs -p)
